const templateItems = $input.all();
const remisiones = $("Clasificar template").all();

if (templateItems.length === 0) {
  throw new Error("No llegó ningún template para renderizar.");
}

if (remisiones.length === 0) {
  throw new Error("No hay remisiones desde el nodo 'Clasificar template'.");
}

function cleanText(value) {
  return String(value ?? "").trim();
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function nl2br(value) {
  return escapeHtml(value).replace(/\r?\n/g, "<br>");
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, " ");
}

function toFileUri(windowsPath) {
  const normalized = cleanText(windowsPath).replace(/\\/g, "/");
  return encodeURI("file:///" + normalized.replace(/^\/+/, ""));
}

function getLogoUri(datos) {
  if (datos.templates_dir) {
    return toFileUri(`${datos.templates_dir}\\images\\DC_logo.jpg`);
  }

  if (datos.template_path) {
    const templateDir = String(datos.template_path).replace(/[\\/][^\\/]+$/, "");
    return toFileUri(`${templateDir}\\images\\DC_logo.jpg`);
  }

  throw new Error("No se pudo construir la ruta del logo porque falta templates_dir o template_path.");
}

function replaceLogoPath(html, logoUri) {
  /*
    Reemplaza únicamente cuando la ruta está dentro de src=""
    Soporta:
    src="./images/DC_logo.jpg"
    src="images/DC_logo.jpg"
    src='./images/DC_logo.jpg'
    src='images/DC_logo.jpg'
  */
  return html.replace(
    /src=(["'])(?:\.\/)?images\/DC_logo\.jpg\1/gi,
    `src="${
      logoUri
    }"`
  );
}

const fields = [
  "numero_remision",
  "id_transport",
  "fecha_envio",
  "proveedor_no",
  "duns_no",
  "pde",
  "ref_pedido"
];

function renderBolsaRows(items) {
  return items.map((item) => `
        <tr>
          <td>${nl2br(item.total_qty)}</td>
          <td>${nl2br(item.qty_per_packaging)}</td>
          <td class="description-cell">${nl2br(item.descripcion)}</td>
          <td>${nl2br(item.part_number)}</td>
          <td>${nl2br(item.packing_code)}</td>
          <td>${nl2br(item.number_of_bags)}</td>
          <td>${nl2br(item.discharge_point)}</td>
        </tr>
`).join("");
}

function renderTuboRows(items) {
  return items.map((item) => `
        <tr>
          <td>${nl2br(item.total_qty)}</td>
          <td>${nl2br(item.qty_per_packaging)}</td>
          <td class="description-cell">${nl2br(item.descripcion)}</td>
          <td>${nl2br(item.part_number)}</td>
          <td>${nl2br(item.number_of_bags)}</td>
          <td>${nl2br(item.discharge_point)}</td>
        </tr>
`).join("");
}

const output = [];

for (let i = 0; i < templateItems.length; i++) {
  const templateItem = templateItems[i];

  const datos = {
    ...(remisiones[i]?.json || {}),
    ...(templateItem.json || {})
  };

  if (!datos.output_name) {
    throw new Error(`Falta output_name en la remisión índice ${i}. Revisa 'Asignar no.Rem'.`);
  }

  if (!datos.formato_audi) {
    throw new Error(`Falta formato_audi en la remisión índice ${i}. Revisa 'Clasificar template'.`);
  }

  const binaryField = Object.keys(templateItem.binary || {})[0] || "data";

  if (!templateItem.binary || !templateItem.binary[binaryField]) {
    throw new Error(`No se encontró el template HTML en binario para la remisión índice ${i}.`);
  }

  const templateBuffer = await this.helpers.getBinaryDataBuffer(i, binaryField);

  let html = templateBuffer.toString("utf8");

  const items = Array.isArray(datos.items) ? datos.items : [];

  if (items.length === 0) {
    throw new Error(`La remisión ${datos.numero_remision || i + 1} no tiene items.`);
  }

  const itemsRows = datos.formato_audi === "tubos"
    ? renderTuboRows(items)
    : renderBolsaRows(items);

  html = html.replace(/<!--\s*{{items_rows}}\s*-->/g, itemsRows);

  // Compatibilidad con templates viejos que todavía tengan Mustache
  html = html.replace(/{{#items}}[\s\S]*?{{\/items}}/g, itemsRows);

  const logoUri = getLogoUri(datos);

  html = replaceLogoPath(html, logoUri);

  for (const field of fields) {
    html = html.replaceAll(`{{${field}}}`, escapeHtml(datos[field]));
  }

  const safeName = safeFileText(datos.output_name || `REM-Audi-${i + 1}.html`);

  const binaryData = await this.helpers.prepareBinaryData(
    Buffer.from(html, "utf8"),
    safeName,
    "text/html"
  );

  output.push({
    json: {
      ...datos,
      output_name: safeName,
      html_generado: true,
      logo_uri: logoUri
    },
    binary: {
      data: binaryData
    }
  });
}

return output;

const TUBOS_FALLBACK = new Set([
  "A15MEAW",
  "A15MEAV"
]);

function cleanText(value) {
  return String(value ?? "").trim();
}

function normalizePartNumber(value) {
  return cleanText(value)
    .toUpperCase()
    .replace(/\s+/g, "");
}

function normalizeFormatoAudi(value) {
  const text = cleanText(value).toLowerCase();

  if (["tubo", "tubos", "rollo", "rollos", "kg"].includes(text)) {
    return "tubos";
  }

  if (["bolsa", "bolsas", "bag", "bags", "pack", "packs", "paquete", "paquetes"].includes(text)) {
    return "bolsas";
  }

  return "";
}

return $input.all().map((item) => {
  const json = { ...item.json };

  const partNumber =
    json.part_number ||
    json.items?.[0]?.part_number ||
    "";

  const normalizedPart = normalizePartNumber(partNumber);

  /*
    Prioridad:
    1. formato_audi desde catálogo, asignado en "Normalizar datos"
    2. formato_audi_catalogo, por seguridad
    3. regla fallback para A15MEAW / A15MEAV
    4. bolsas por defecto
  */
  const formatoDesdeCatalogo =
    normalizeFormatoAudi(json.formato_audi) ||
    normalizeFormatoAudi(json.formato_audi_catalogo) ||
    normalizeFormatoAudi(json.items?.[0]?.formato_audi_catalogo);

  const formatoAudi = formatoDesdeCatalogo ||
    (TUBOS_FALLBACK.has(normalizedPart) ? "tubos" : "bolsas");

  if (!json.templates_dir) {
    throw new Error("No se encontró templates_dir. Revisa que venga desde 'Preparar archivo trigger' y 'Normalizar datos'.");
  }

  if (!json.output_name) {
    throw new Error("No se encontró output_name. Revisa que 'Asignar no.Rem' haya asignado el nombre final.");
  }

  json.formato_audi = formatoAudi;

  json.formato_audi_origen = formatoDesdeCatalogo
    ? "catalogo"
    : TUBOS_FALLBACK.has(normalizedPart)
      ? "fallback_part_number"
      : "default_bolsas";

  json.template_path = formatoAudi === "tubos"
    ? `${json.templates_dir}\\REM-Template-Audi-Tubos.html`
    : `${json.templates_dir}\\REM-Template-Audi-Bolsas.html`;

  return {
    json
  };
});

function cleanText(value) {
  return String(value ?? "").trim();
}

function safeFileName(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, " ");
}

return $input.all().map((item, index) => {
  const json = { ...item.json };

  if (!json.temp_dir) {
    throw new Error(`Falta temp_dir en el item ${index}. Revisa 'Preparar archivo trigger' y 'Normalizar datos'.`);
  }

  if (!json.output_dir) {
    throw new Error(`Falta output_dir en el item ${index}. Revisa 'Preparar archivo trigger' y 'Normalizar datos'.`);
  }

  if (!json.output_name) {
    throw new Error(`Falta output_name en el item ${index}. Revisa 'Asignar no.Rem'.`);
  }

  const htmlName = safeFileName(json.output_name);
  const pdfName = htmlName.replace(/\.html?$/i, ".pdf");

  const htmlPath = `${json.temp_dir}\\${htmlName}`;
  const pdfPath = `${json.output_dir}\\${pdfName}`;

  return {
    json: {
      ...json,

      html_name: htmlName,
      html_path: htmlPath,

      pdf_name: pdfName,
      pdf_path: pdfPath
    },
    binary: item.binary
  };
});

